(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["eu"] = {"ui":{"skip":"Joan edukira","back":"← Itzuli AI-gilera","lang.button":"Hizkuntza: {name}","lang.dialog":"Aukeratu hizkuntza bat","lang.search":"Bilatu hizkuntzak","lang.none":"Ez dago hizkuntzarik bat datorrenik","lang.notYet":"{name} ez dago oraindik itzulita","theme.aria":"Aldatu gaia: argia, iluna edo beltza","theme.toLight":"Aldatu gai argira","theme.toDark":"Aldatu gai ilunera","theme.toBlack":"Aldatu gai beltzera (benetako beltza, OLED pantailentzat leuna)","words.underline":"Azpimarratu hitz hauek orrian","words.underlineHelp":"Pasatu sagua edo sakatu puntuz azpimarratutako hitz baten gainean, zer esan nahi duen ikusteko.","index.title":"AI-gile: zure AI garapen-taldea, taula bakarrean","index.description":"AI-gile AA bidezko programazio-taldeentzako kanban taula bat da. Zu lo zaudela lan egiten dute; zuk pila labur bat jasotzen duzu, erabaki, probatu eta onartzeko gauzekin.","hero.logoAlt":"AI-gile taularen ikonoa","hero.h1.html":"Zure AI garapen-taldea, taula&nbsp;bakarrean.","hero.alpha":"🐣 Aurre-alfa itxia","hero.alphaTitle":"Goiztiarra eta bukatu gabea: eskerrik asko probatzeagatik!","hero.lede":"Zu lo zaudela eraikitzen dute. Esnatzean pila labur bat izango duzu zain: galdera batzuk, probatzeko gauza batzuk, diamante more bat edo bi. Klik egin, onartu, eta itzuli zure kafera.","dl.windows":"Windows aplikazioa","dl.browser":"Erabili nabigatzailean","dl.messenger":"📱 Messenger zure telefonorako","dl.soon":"Laster","dl.notify":"🔔 Abisatu irekitzen denean","dl.notifySmall":"Alfa edo beta","hero.secondary":"Agile, baina taldeak ez du inoiz zutik egindako bilerako kafearen beharrik. (Zutik egindako bilerak egiten dituzte, hala ere.)","pitch.h2":"AI-gile nahi adina hitzetan","pitch.lede":"Aukeratu luzera bat, hitz batetik 144ra. Luzera bakoitza bere deskribapena da, tamaina horretarako idatzia. Arrastatu graduatzailea edo erabili gezi-teklak.","pitch.rangeLabel":"Luzera hitzetan","pitch.dice":"🎲 beste bertsio bat","pitch.words.one":"{n} hitz","pitch.words.other":"{n} hitz","pitch.letters.one":"{n} letra","pitch.letters.other":"{n} letra","pitch.chars.one":"{n} karaktere","pitch.chars.other":"{n} karaktere","count.line.html.one":"{n} txartel taulan orain","count.line.html.other":"{n} txartel taulan orain","features.aria":"Zer egiten duen","f.pile.h":"Pila bakarra zuretzat","f.pile.html":"<b>Zuretzat</b> atalak zure zain dagoen guztia biltzen du, proiektu guztietatik: galderak, probatzeko gauzak, gizakiak bakarrik egin ditzakeen zereginak. Zure ilarak esaten dizu zer datorren eta zenbat denbora behar duen.","f.sleep.h":"Zu lo zaudela lan egiten duten taldeak","f.sleep.p":"Proiektu bakoitzak taldeburu bat eta AA agenteen talde bat ditu. Egin iruzkina txartel batean eta taldea esnatu egingo da, lana egin eta itzuliko dizu gizaki nekatu batek jarrai ditzakeen urratsekin.","f.tester.h":"AA probatzaile batek aurretik egiaztatzen du","f.tester.p":"Ezer zuregana iritsi aurretik, probatzaile batek aplikazioaren kopia batean urratsak jarraitzen ditu eta ikusi duena erakusten du, pantaila-argazkiarekin. Begiratu pasatakoak azkar eta onartu klik batekin.","f.proof.h":"Frogak, ez promesak","f.proof.p":"Entrega bakoitzak zer aldatu den erakusten du: fitxategiak, diff-a, pantaila-argazkiak. Ez duzu aplikazio bakoitza ireki behar bukatuta dagoen jakiteko.","f.chat.h":"Berriketan zure taldeburuekin","f.chat.p":"Discord estiloko barra bat: ikono bat proiektu bakoitzeko, diamante moreak zu behar zaituenarentzat. Bidali ideia bat taldeburuari; txartel eta plan bihurtuko du, ✅ Go botoiarekin.","f.tidy.h":"Bere burua txukun mantentzen du","f.tidy.p":"Elkarrekin lotutako txartelak bat egiten dute, titulu nahasiak zuzentzen dira, eta token-kontrolak kodea arin mantentzen du. Aldatzeko gauza gutxiago, pentsatzeko gutxiago.","f.private.h":"Zurea, zure ordenagailuan","f.private.li1":"Taula zure makinan exekutatzen da eta zuri bakarrik erantzuten dio.","f.private.li2":"Pertsonen arteko mezu pribatuak muturretik muturrera zifratuta daude.","f.private.li3":"Konturik gabe, aztarnaririk gabe, cookierik gabe.","f.lang.h":"Zure hizkuntzan","f.lang.p":"120 hizkuntza baino gehiago, nederlanderatik, galesetik eta japonieratik piratera, Yodara eta klingonera, termino teknikoetarako ingelesera itzultzeko aldaketa azkarrarekin.","f.service.h":"Ideia batetik benetako zerbitzu batera","f.service.p":"AIarekin jendeak orain erabiltzen duen zerbait eraiki duzu? Markatu zerbitzu gisa eta taulak ondo martxan izaten lagunduko dizu: erabilgarritasun-egiaztapenak, egoera-orri publikoa, txostena duten intzidenteak, Go bat behar duten aldaketak, egunero egiaztatutako babeskopiak. Laguntzak urrats bakoitza erakusten dizu bidean.","msgr.h2":"AI-gile Messenger: zure taldea poltsikoan","msgr.p1":"Hitz egin zure AI taldearekin taula ireki gabe. Txateatu zure proiektuburuekin eta lagunekin, eta ikusi txartel baten proba-urratsak eta erantzun, dena telefonotik.","msgr.p2":"Lotzeko, eskaneatu zure taulako QR kode bat. Lehen aldia? Demo-txat atsegin batek dena erakutsiko dizu.","msgr.when":"Lehenik Android, gero telefonoetarako eta iPhonerako web bertsio bat.","msgr.who":"Zure proiektuburua","msgr.b1":"Modu ilunaren konponketa prest dago. Proba-urratsak nahi dituzu?","msgr.b2":"Bai, mesedez!","msgr.b3":"1. Ireki Ezarpenak. 2. Aukeratu Iluna. Ondo ikusten da?","tl.aria":"Denbora-lerroa lehen elkarrizketatik ibilbide-orrira","tl.h2":"Lehen txatetik datorrenera","tl.lede":"Benetako datak eta orduak, zure ordu-zonan. Gaurtik aurrera plana da, daturik agindu gabe.","tl.today":"Gaur","tl.planned":"planifikatuta","tl.cards.one":"{n} txartel","tl.cards.other":"{n} txartel","join.h2":"Egin bat","join.lede":"AI-gile AuDHDa eta buru-osasunarekin borroka batzuk dituen bizardun xelebre batek eta agente pazientzia handiko askok eraikitzen dute. Pribatua da oraingoz, lagunekin alfa itxian. Probatu nahiko zenuke irekitzen denean?","join.btn":"Eman interesa","join.small":"Posta elektronikoz idatziko dizugu, besterik ez","footer.tag":"AI-gile. Aztarnaririk gabe, cookierik gabe, zutik egindako bilerako kaferik gabe.","footer.licence":"Negozio-lizentzia","footer.status":"Egoera","footer.privacy":"Zer gordetzen dugun","footer.thanks":"Deiak ChilledChat-i esker","form.sending":"Bidaltzen…","form.failed":"Hori ez da ondo atera: saiatu berriro geroago.","form.offline":"Ezin izan da AI-gilerekin konektatu: saiatu berriro geroago.","form.keep":"Zuri erantzuteko bakarrik erabiltzen dugu, eta gero ezabatu egiten dugu. Aztarnaririk gabe, cookierik gabe.","form.keepLink":"Zer gordetzen dugun","interest.title":"AI-gile: abisatu alfa irekitzen denean","interest.description":"Utzi zure posta elektronikoa AI-gileren alfa edo beta itxia noiz irekitzen den jakiteko.","interest.h1":"🔔 Abisatu irekitzen denean","interest.lede":"AI-gile aurre-alfa itxian dago. Utzi zure posta elektronikoa eta behin idatziko dizugu, zuretzako lekua dagoenean.","interest.email":"Zure posta elektronikoa","interest.which":"Zein proba?","interest.alpha":"Alfa itxia: goiztiarra, latza, aldaketa asko","interest.beta":"Beta: egonkorragoa, geroagokoa","interest.both":"Edozein, zein lehenago ireki","interest.submit":"Jarri nazazu zerrendan","interest.thanks":"Eskerrik asko! Zerrendan zaude.","licence.title":"AI-gile: negozio-lizentzia","licence.description":"Erabiltzen al duzu AI-gile zure negozioan? Eskatu negozio-lizentzia doakoa.","licence.h1":"📜 Negozio-lizentzia","licence.lede":"Lanean erabiltzen al duzu AI-gile? Esan zeintzuk zareten eta zer egiten duzuen. Onik egiten badu, lizentzia doakoa da.","licence.company":"Enpresa","licence.website":"Webgunea","licence.what":"Zer egiten duzuen","licence.how":"Nola laguntzen dion munduari","licence.email":"Posta elektronikoa","licence.submit":"Eskatu","licence.thanks":"Eskerrik asko! Posta elektronikoz erantzungo dizugu.","status.title":"AI-gile egoera","status.h1":"AI-gile egoera","status.quiet":"Dena lasai","status.intro":"AI-gile badabil orain? Orri honek 5 minuturo egiaztatzen ditu webgunea, taulak partekatzea, deiak eta deskarga.","status.up":"Badabil ({ms} ms-tan erantzun du)","status.slow":"Ez dio azken egiaztapenari erantzun, berriro saiatzen","status.down":"Erorita: ez die azken bi egiaztapenei erantzun","status.svc.web":"Webgunea","status.svc.web.offers":"Gune hau: zer den AI-gile, eta interes-formularioa","status.svc.boards":"Taulak partekatzea","status.svc.boards.offers":"Taula publikoak, lagunen arteko mezuak eta gonbidapenak","status.svc.calls":"Deiak","status.svc.calls.offers":"Ahotsa, bideoa eta pantaila partekatzea AI-gile-n","status.svc.download":"Deskarga","status.svc.download.offers":"Windowserako instalatzailea eta gonbidapen-estekak","status.checking":"Egiaztatzen…","status.offline":"Ezin da egoera-zerbitzura heldu orain (berriro saiatzen)","status.updated":"eguneratua {ago}","status.justNow":"orain bertan","status.min":"duela {n} min","status.hours":"duela {n} h","status.days":"duela {n} egun","privacy.title":"AI-gile: zer gordetzen dugun","privacy.h1":"Zer gordetzen dugun","privacy.lede":"Laburbilduz: bidaltzen diguzuna bakarrik, eta ez denbora luzez.","privacy.only":"Bidaltzen diguzuna bakarrik: formulario batean idazten duzuna, zure posta elektronikoa adibidez. Zuri buruzko beste ezer ez.","privacy.sealed":"Zigilatu egiten da, gure zerbitzariak irakurri ez dezan: zure nabigatzailean, irten aurretik (nabigatzaile zaharrago batean, iristen den unean). Gure taulak bakarrik ireki dezake.","privacy.server":"Zerbitzaritik ezabatzen da gure taulara iritsi bezain laster. 30 egunen ondoren oraindik han dagoena ere ezabatu egiten da, hala ere.","privacy.board":"Gure taulan gordetzen dugu zuri erantzun arte bakarrik, eta gero handik ere ezabatzen dugu.","privacy.none":"Aztarnaririk gabe, cookierik gabe, analitikarik gabe.","privacy.local":"Zure hizkuntza eta modu argiaren edo ilunaren aukera zure nabigatzailean bertan geratzen dira. Ez zaizkigu inoiz bidaltzen.","privacy.ask":"Lehenago ezabatzea nahi duzu? Erantzun gure mezu elektronikoari eta esaiguzu.","live.h2":"Ikusi nola eraikitzen den, zuzenean","live.caption":"Txartel guztiak ezkutuan daude: lanaren forma ikusten duzu, ez hitzak.","live.watching.one":"zuzenean: {n} ikusten","live.watching.other":"zuzenean: {n} ikusten","live.last.now":"Azken txartela orain bertan mugitu da","live.last.min.one":"Azken txartela duela {n} min mugitu da","live.last.min.other":"Azken txartela duela {n} min mugitu da","live.last.hour.one":"Azken txartela duela {n} ordu mugitu da","live.last.hour.other":"Azken txartela duela {n} ordu mugitu da","live.last.day.one":"Azken txartela duela {n} egun mugitu da","live.last.day.other":"Azken txartela duela {n} egun mugitu da","live.offline":"Zuzeneko taulak atsedentxo bat hartzen ari da. Itzuli laster.","live.cols":"Backlog|Egiteko|Egiten|Taldeak aztertzen|Zuk probatzeko|Taldearentzat|Eginda"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotak.","Delegatuta."]},{"n":2,"texts":["Robotak lanean.","Agenteak, antolatuta.","Ideiak, eraikita."]},{"n":3,"texts":["Kanbana robotentzat.","Ideiak ezaugarri bihurtzen.","Agente-kanban doakoa."]},{"n":5,"texts":["Agenteek zuzendutako kanban taula.","Zuk idatzi, agenteek eraiki.","Doakoa, lokala, probatua, apur bat zentzugabea."]},{"n":8,"texts":["AA agenteek lan egiten duten kanban taula doakoa.","Idatzi ideia bat. Agenteek eraikiko dute. Zuk onartu.","Agile gizaki batentzat eta robot pazientzia handiko askorentzat."]},{"n":13,"texts":["Zure ordenagailuko kanban taula, non AA agenteek txartelak hartzen eta lana egiten duten.","Idatzi ideia bat. Agenteen talde batek eraikiko du. Probatzaile batek egiaztatuko du.","Doakoa, konturik gabe, aztarnaririk gabe: taula bat, robot batzuk, eta zu agintean."]},{"n":21,"texts":["AI-gile AA bidezko programazio-agenteekin lan egiteko kanban taula bat da. Haiek hartzen dituzte txartelak; zuk probatu eta onartzen dituzu.","Proiektu bakoitzak taldeburu bat eta AA agenteen talde bat izaten ditu. Egin iruzkina edozein txartelean eta taldea lanean hasiko da.","Zure ordenagailuan exekutatzen den zeregin-taula pertsonal eta doakoa, konturik eta aztarnarik gabekoa. Langileak robotak dira. Baiezkoa ematen duena zu zara."]},{"n":34,"texts":["Ideiak taulan jartzen dituzu. AA agenteen talde batek ezaugarri funtzionaletan bihurtzen ditu, probatu egiten ditu eta probatzeko urratsekin itzultzen dizkizu. Ezer ez da bukatutzat jotzen zuk esan arte.","AI-gile etxean egindako kanban taula bat da, Richek eraiki zuena orain kudeatzen dituen agenteen laguntza handiarekin. Doakoa da, zure ordenagailuan exekutatzen da eta lagunekin partekatzen da, ez saltzen.","Imajinatu ohiko kanban taula bat, Backlogetik Eginda arteko zutabeekin, baina txartelak AA agenteek hartzen dituztela. Aurrerapenaren berri ematen dute, galdetzen dute trabatuta daudenean, eta beti zure baiezkoaren zain geratzen dira."]},{"n":55,"texts":["AI-gile kanban taula bat da, eta bertako taldea AA agenteek osatzen dute. Proiektu bakoitzak lana planifikatzen duen taldeburu bat eta eraikitzen duten laguntzaile batzuk ditu. Ezaugarri bat prest dagoenean, AA probatzaile batek probatu eta pantaila-argazkia ateratzen du, eta gero zure pilara iristen da. Onartu, edo egin iruzkina eta berriro lantzen dute.","Pertsona baten modua izan zen aldi berean AA bidezko programazio-saio asko jarraitzeko, eta benetako taula bihurtu zen. Zure makinan exekutatzen da, ez du konturik behar eta ez dauka aztarnaririk. Doakoa da lagunentzat eta jakin-minez daudenentzat. Bukatu gabe ere badago, beraz espero ertz latz batzuk eta noizbehinkako sorpresaren bat.","Hau da bertsio zintzoa. Zuk bururatu behar dituzu oraindik ideiak, eta zuk egiaztatu behar dituzu emaitzak. AI-gilek tartean dagoen guztia egiten du: txartelak ordenean mantentzen ditu, agente egokia esnatzen du iruzkina egitean, zehazki zer aldatu den erakusten du, eta dena pila labur batean uzten du zuretzat."]},{"n":89,"texts":["AI-gile zure ordenagailuan exekutatzen duzun kanban taula doakoa da. Pertsonen ordez, proiektu bakoitzak AA agenteen talde bat du: zure ideiak txartel eta plan bihurtzen dituen taldeburu bat, eta txartelak lehentasun-ordenan hartzen dituzten laguntzaileak. Zerbait eraikita dagoenean, AA probatzaile batek proba-urratsak jarraitzen ditu eta ikusi duena erakusten dizu. Gero Zuretzat izeneko pila batean geratzen da zain. Onartzen duzu, edo iruzkina egiten duzu eta taldeak berriro saiatzen da. Ezer ez da inoiz Eginda zutabera iristen zu gabe.","Ez dituzun espero agian gauza batzuk. Gaueko zaintzak Egiteko zutabea beteta mantentzen du zu lo zaudela, zure erantzunik behar ez duten txartelak aukeratuz. Token-kontagailuak erakusten du agenteek gaur eta aste honetan zenbat erabili duten, eta Token-gabeko Moduak gastatzeari uzteko esaten die. Lagunei mezuak bidal diezazkiezu, eta mezu pribatuak muturretik muturrera zifratuta daude. Taulak 120 hizkuntza inguru hitz egiten ditu, nederlandera, flandestarra, pirata eta klingonera barne. Horietako ezerk ez du zentimorik balio, eta inork ez dizu saltzen saiatzen ere.","AI-gile proiektu txiki eta pertsonala da, ez enpresa bat. Richek AA bidezko programazio-proiektu batzuk zaindu nahi zituen aplikazio bakoitza irekitzeke zer moduz zeuden begiratzeko, beraz berak eta agenteek horretarako taula bat eraiki zuten, eta gero taula bera erabili zuten gainerakoa eraikitzeko. Aurre-alfa itxian dago, hau da, funtzionatzen du, gehienetan, lagun sorta txiki batentzat. Ez dago prezio-orririk, ez albisteak bidaltzen dituenik eta ez hazkunde-planik. Erabilgarria iruditzen bazaizu, probatzeko eskatu dezakezu apur bat gehiago irekitzen denean."]},{"n":144,"texts":["AI-gile gizaki bakar batentzako eta AA agente askorentzako kanban taula bat da. Zure ordenagailuan exekutatzen da eta guztiz doakoa da. Proiektuak gehitzen dituzu, eta proiektu bakoitzak taldeburu bat eta talde txiki bat izaten ditu. Taldeburuarekin berriketan aritzen zara, Discorden antzera, eta ideia bat deskribatzen duzu; taldeburuak txartel eta plan bihurtzen du, eta Go sakatzeko zain geratzen da. Taldeak txartelak lehentasun-ordenan egiten ditu, hizkuntza-ereduentzat egindako komando-lerro sinple bat erabiliz. Ezer zuregana itzuli aurretik, AA probatzaile batek aplikazioaren kopia batean urratsak jarraitzen ditu eta pantaila-argazki bat eransten du. Amaitutako lana zure pilara iristen da, aldatutako fitxategiekin eta diff-arekin. Onartzen duzu, edo iruzkin bat uzten duzu eta taldea esnatu eta berriro saiatzen da. Zuk bakarrik mugi dezakezu txartel bat Eginda zutabera.","AI-gilerekin egun bat, gutxi gorabehera. Arratsaldean iruzkin batzuk uzten dituzu: botoi hau toki okerrean dago, zerrenda hori ordenatu beharko litzateke, modu iluna izan genezake. Ohera zoaz. Agenteek iruzkinak irakurtzen dituzte, aldaketak egiten dituzte, probatzen dituzte eta itzultzen dizkizute. Egiteko zutabea hustuz gero, gaueko zaintzak backlogetik betetzen du, zure erantzunik behar ez duten txartelekin. Goizean pila labur bat dago: galdera pare bat eta probatzeko gauza batzuk, bakoitza lo gaizto dagoen pertsona batek jarrai ditzakeen urratsekin eta funtzionatzen duela erakusten duen pantaila-argazkiarekin. Klik eginez igarotzen zara, onak onartzen dituzu eta gainerakoak itzultzen dituzu. Token-kontagailuak erakusten du horrek guztiak zer erabili duen, eta Token-gabeko Modua aste mehe horietarako dago. Gero gosaltzen duzu, agenteek oraindik laguntzen ezin dutena. Kafea, berriz, lasai edan dezakezu.","Lehenik, zer ez den AI-gile. Ez da startup bat, ez dago salgai, eta inork ez ditu zure datuak biltzen. Zure ordenagailuan exekutatzen den taula doakoa da, konturik gabe, aztarnaririk gabe eta cookierik gabe. Zer den: AA bidezko programazio-proiektu guztiak aldi berean ikusteko leku txukun bat, agente-talde batek txartelak egiten dituela eta zuk erabakiak hartzen dituzula. Lotutako txartelak batzen ditu, titulu nahasiak zuzentzen ditu, eta kodea zein arin mantentzen den zaintzen du. 120 hizkuntza inguru hitz egiten ditu, nederlandera eta flandestarretik pirata eta klingonera. Lagunek elkarri mezuak bidal diezazkiokete, pribatuki eta zifratuta. Richek eta agente pazientzia handiko askok eraiki zuten, gehienbat bera bera erabiliz. Aurre-alfa itxian dago, beraz toki batzuetan latza da. Dibertigarria dirudiela uste baduzu, eskatu ondo eta agian goiz sartuko zara."]}],"quips":{"1":"Hitz bat. Ausarta. Agian gehiegi.","3":"Hiru hitz. Produktu-orri gehienak baino zintzoagoa jada.","8":"Zortzi hitz. Zutik egindako bilera bat baino laburragoa oraindik.","21":"Luzerak story point-ak dira, bide batez. Noski baietz.","55":"Berrogeita hamabost hitz. Bi txartel bukatu dira hau irakurtzen ari zinen bitartean.","144":"Hori da luzea. Ez dago 233rik. Agenteak ohera joan dira."}},"timeline":{"first-idea.name":"Lehen ideia","first-idea.line":"Lehen elkarrizketa, kodeik existitu aurretik.","first-board.name":"Lehen taula","first-board.line":"Bere eraikuntza bera jarraitzen duen taula: txartelak, zutabeak, arrastatu eta jaregin, proiektuak.","team-roles.name":"Taldea eta rolak","team-roles.line":"Agente-profilak, talde-txantiloiak, guneak eta nork zer egiten duen.","install.name":"Instalazioa eta bertsioak","install.line":"Lagun batek instala dezakeen zip bat, auto-eguneraketak, kanalak eta atzera egitea.","usage-saver.name":"Erabilera-aurrezlea","usage-saver.line":"Neurtu zenbat kostatzen diren exekuzioak, mantendu kodea arin, aurreztu zure muga.","friends.name":"Lagunak eta partekatzea","friends.line":"Mezu pribatuak, errele nahastua, gonbidapenak, rolak eta proiektu partekatuak.","languages.name":"Hizkuntzak","languages.line":"Pantailako testu guztiak hizkuntza-fitxategi batean, nederlandera eta flandestarra lehenengo.","ai-tester.name":"AA probatzailea","ai-tester.line":"Probatzaile batek entrega bakoitza aurretik egiaztatzen du eta ikusi duena erakusten du.","website.name":"Webgunea","website.line":"aigile.lol, teaser-a eta denbora-lerro hau.","streaming.name":"Txata eta streaming-a","streaming.line":"Discord, Twitch, OBS, streamer modua, GIFak eta emojiak.","no-ai.name":"AArik gabeko edizioa","no-ai.line":"AArik gabe programatzen dutenentzako taula, eta taula publikoak.","night-watch.name":"Gaueko zaintza","night-watch.line":"Zaindari batek eta Scrum Master batek taldeak zereginean mantentzen dituzte zu lo zaudela.","p-more.name":"Gainerako guztia","p-more.line":"Oraindik txandaren zain dauden ideia txikiagoak.","p-android.name":"Telefonoa eta Android","p-android.line":"Iritsi zure taulara telefonotik, gero Android aplikazio natibo batera.","p-release.name":"Alfa eta haratago","p-release.line":"Alfa itxia, webgune bizia, gero beta.","p-languages.name":"Hizkuntza gehiago","p-languages.line":"Ehun hizkuntza baino gehiago, eta murgiltze modua ikasleentzat.","p-engines.name":"AA motor gehiago","p-engines.line":"Aukeratu Claude, Codex edo Gemini agente bakoitzeko.","p-pro.name":"Praktika profesionala","p-pro.line":"Arrisku-etiketak, bateratze-ateak, intzidentzia-txartelak eta babes-hesiak.","p-self.name":"Zure zaintza","p-self.line":"Nekatuta modua, norberaren zaintzarako gogorarazpenak eta 4:20.","p-servers.name":"Zerbitzariak eta eskala","p-servers.line":"Zerbitzari-ezarpen orokorrak, rolak eta hazkundea planifikatzea.","p-livestream.name":"Streaming-aren gehigarriak","p-livestream.line":"Twitch txata, emoji pertsonalizatuak eta zuzeneko ikuspegi publikoa."},"words":{"button":"📖 Termino teknikoak","h":"📖 Hitzak azalduta","intro":"AI-gile-n aurkituko dituzun hitzak, hizkera errazean: eraikitzea, seguru aldatzea, erabiltzen dutenentzat martxan mantentzea eta AIarekin talde gisa lan egitea.","search":"Bilatu hitz bat…","none":"Ez dago horrekin bat datorren hitzik.","close":"Itxi","count":{"one":"{count} hitz","other":"{count} hitz"},"groups":[{"id":"build","name":"🛠️ Eraikitzea"},{"id":"change","name":"🔀 Seguru aldatzea"},{"id":"run","name":"🛎️ Zerbitzu bat martxan izatea"},{"id":"team","name":"🤝 Talde gisa lan egitea (baita AIarekin ere)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Proiektuaren kode-karpeta eta commit-en historia osoa, normalean GitHub-en ere gordetzen dena.","also":["repositorioa"]},{"id":"branch","g":"build","word":"Branch","text":"Kodeko lan-lerro bereizi bat, aldaketak bertsio nagusia ukitu gabe egiteko.","also":["branchak","branch-ak"]},{"id":"commit","g":"build","word":"Commit","text":"Kodearen argazki gordea, aldatutakoaren ohar labur batekin. Beti itzul zaitezke horietako batera.","also":["commitak","commit-ak"]},{"id":"push","g":"build","word":"Push","text":"Gordetako argazkiak (commit-ak) ordenagailu honetatik GitHub-era bidaltzea, babeskopia izan eta partekatuta egoteko."},{"id":"merge","g":"build","word":"Merge","text":"Branch baten aldaketak bertsio nagusian berriro batzea."},{"id":"pr","g":"build","word":"Pull request","text":"Branch baten aldaketak aztertu eta bertsio nagusian bateratzeko eskaera.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kodea txukuntzea egiten duena aldatu gabe: fitxategi txikiagoak, izen argiagoak, errepikapen gutxiago."},{"id":"bug","g":"build","word":"Bug","text":"Behar bezala ez dabilen zerbait.","also":["bugak","bug-ak"]},{"id":"test","g":"build","word":"Proba","text":"Amaitutako lan bat probatzea, eskatutakoa egiten duela egiaztatzeko, onartu aurretik.","also":["probak","probatu","probatzeko","probaren"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Ingelesezko quality assurance-ren laburdura, kalitatearen bermea: zerbait zuzenean jarri aurretik exekutatzen diren egiaztapen automatikoak. QA gorri dagoenean, zerbaitek huts egin du, eta ezin da zuzenean jarri hori konpondu arte.","also":["kalitate-kontrola","kalitate-kontrolak","kalitatearen bermea"]},{"id":"deploy","g":"change","word":"Deploy","text":"Bertsio berri bat martxan jartzea, adibidez jendeak erabiltzen duen zerbitzari batean."},{"id":"release","g":"change","word":"Argitalpena","text":"Izena duen amaitutako lan-sorta bat, batera zuzenean jartzen dena, zer aldatu den azaltzen duten ohar laburrekin. 🚀 Argitalpenak eginda dauden txarteletatik idazten ditu oharrak.","also":["argitalpenak","release","bertsioa"]},{"id":"rollback","g":"change","word":"Atzera egitea","text":"Ondo zebilen azken bertsiora itzultzea, berri batek arazoak ematen dituenean. AI-gile-n, aldaketa bakoitzean idatzitako desegiteko urratsekin egiaztapen-zerrenda bat egiten du.","also":["rollback","atzera egin","atzera egin da"]},{"id":"live","g":"change","word":"Zuzenean","text":"Jendeak erabiltzen duen benetako bertsioa, gauzak probatzeko kopia baten aldean. Garatzaileek ekoizpena ere esaten diote.","also":["ekoizpena","live","produkzioa"],"noTip":1},{"id":"change","g":"change","word":"Aldaketa","text":"Jendeak behar duen zerbaitean planifikatutako aldaketa bat, aurrez idatzita: zer, zergatik, arriskua, noiz eta nola desegin. Hasi bat 🔀 Aurkeztu aldaketa bat botoiarekin.","also":["aldaketak","aldaketa-eskaera","aldaketa-eskaerak"],"noTip":1},{"id":"risk","g":"change","word":"Arriskua","text":"Gaizki atera daitekeen zerbait, zein litekeen eta zein larria litzatekeen kontuan hartuta puntuatua. ⚠️ Arriskuak zerrenda bakarrean gordetzen ditu, puntuazio altuena lehenik, bakoitza berriro begiratzeko data batekin.","also":["arriskuak","arrisku-erregistroa"]},{"id":"chgwin","g":"change","word":"Aldaketa-leihoa","text":"Aldaketak zuzenean jar daitezkeen uneak, adibidez astearte arratsalde lasai bat. Leiho batetik kanpo ezin da aldaketa-txartel bat amaitu, larrialdi bat ez bada.","also":["aldaketa-leihoak"]},{"id":"gonogo","g":"change","word":"Go / No go","text":"Bozketa azkar bat aldaketa bat zuzenean jarri aurretik: onartu behar duen pertsona bakoitzak Go edo No go esaten du. Ados daudenean bakarrik aurrera egiten du.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Onarpena","text":"Lana hasi aurretik bai baten zain egotea. Lagun batek sortzen duen txartela, edo aldaketa bat, ✅ Onarpenak atalean itxaroten du zuk onartu edo baztertu arte.","also":["onarpenak"]},{"id":"quiettime","g":"change","word":"Ordu isila","text":"Denbora tarte bat, hala nola zuzeneko emanaldi bat, demo bat edo gaua, ezer zuzenean jartzen ez dena. Taldeek lanean eta probatzen jarraitzen dute, baina zuzenean jartzeak amaitu arte itxaroten du. Beste leku batzuetan aldaketa-izozketa deitzen zaio.","also":["ordu isilak","aldaketa-izozketa","change freeze"]},{"id":"service","g":"run","word":"Zerbitzua","text":"Zuk eraiki duzun eta jendeak behar duen zerbait, webgune edo aplikazio bat adibidez, martxan jarrai dezan zaintzen dena. Markatu «Proiektu hau zerbitzu bat da» eta esan zer eskaintzen duen, nork erabiltzen duen eta nor dagoen guardian.","also":["zerbitzuak"]},{"id":"uptime","g":"run","word":"Erabilgarritasun-egiaztapena","text":"Egiaztapen automatiko bat, minutu gutxiro, zure zerbitzuak oraindik erantzuten duela ziurtatzeko. Hainbat aldiz jarraian huts egiten badu, AI-gile-k berak irekitzen du intzidente-txartel bat.","also":["erabilgarritasuna","uptime","erabilgarritasun-egiaztapenak"]},{"id":"statuspage","g":"run","word":"Egoera-orria","text":"Zerbitzu batek funtzionatzen duen ala ez erakusten duen orri publikoa (berdea, laranja edo gorria), azken berriarekin, erabiltzaileek galdetu beharrean begiratu ahal izan dezaten.","also":["egoera-orriak"]},{"id":"incident","g":"run","word":"Intzidentea","text":"Erabiltzen dutenentzat oraintxe bertan hautsita dagoen zerbait, webgunea erorita egotea adibidez. 🔥 Intzidente-txartel batek ilara saltatzen du: berriro martxan jartzea da lehena.","also":["intzidenteak","gorabehera"]},{"id":"major","g":"run","word":"Intzidente larria","text":"Intzidente handi bat: jende asko kaltetuta, edo dirua edo datuak arriskuan. Botoi batek talde guztiak jartzen ditu horretan (erlauntza), guardian dagoena esnatzen du eta egoeraren berri eskatzen du 30 minuturo.","also":["intzidente larriak","major incident"]},{"id":"oncall","g":"run","word":"Guardian","text":"Zerbait hausten denean erantzuten duena izatea, gauez ere bai. Zerbitzu bakoitzak guardian dagoen talde-kide bat du, bere intzidenteetarako lehenengo esnatzen dena.","also":["guardia","guardiak","on-call"]},{"id":"replyby","g":"run","word":"Erantzun-epea","text":"Txartel batek lehen erantzunaren zain zenbat denbora egon daitekeen, adibidez ordubete intzidente baterako. Ondoren erloju gorri bat jartzen zaio, ezer isilean ahaztu ez dadin. Erantzun-helburua ere deitzen zaio.","also":["erantzun-epeak","erantzun-orduak","erantzun-helburua"]},{"id":"postmortem","g":"run","word":"Intzidentearen ondoko azterketa","text":"Intzidente baten ondoren atzera begiratze labur bat: zer gertatu zen, zerk lagundu zuen eta zer aldatu, inori errua bota gabe. Intzidente bat ezin da itxi hori gabe.","also":["post-mortem","postmortem","ondoko azterketa"]},{"id":"problem","g":"run","word":"Arazoa","text":"Intzidente baten edo gehiagoren atzean ezkutatuta dagoen kausa. 🧩 Arazo-txartel batek behin eta berriz itzultzen diren intzidenteak biltzen ditu, kausa aurkitu eta betiko konpon dadin.","also":["arazoak"],"noTip":1},{"id":"rootcause","g":"run","word":"Kausa nagusia","text":"Zerbait hautsi izanaren benetako arrazoia, ez bakarrik gaizki zihoala ikusi zenuena. Konpondu kausa nagusia eta intzidenteak ez du berriro itzuliko.","also":["kausa nagusiak","oinarrizko kausa","erroko kausa"]},{"id":"workaround","g":"run","word":"Aldi baterako konponbidea","text":"Gauzak martxan mantentzeko modu bat benetako konponketa prest egon arte, adibidez zerbait berrabiaraztea trabatzen denean. Arazo-txartelean idatzita geratzen da, inork berriro asmatu behar ez dezan.","also":["aldi baterako konponbideak","workaround"]},{"id":"knownerror","g":"run","word":"Ezagutzen den errorea","text":"Kausa ulertuta duen eta aldi baterako konponbidea duen arazo bat, oraindik konpondu ez dena. 🧩 Ezagutzen diren erroreak zerrendan biltzen ditu, denek aldi baterako konponbidea erabil dezaten berriro ikertu beharrean.","also":["ezagutzen diren erroreak","errore ezaguna"]},{"id":"runbook","g":"run","word":"Runbook","text":"Pausoz pausoko jarraibideak arazo mota ezagun bat konpontzeko, beti modu berean eta azkar egin dadin. Intzidente handi baten ondoren taldeak bat proposa diezazuke zuk onar dezazun.","also":["runbook-ak","eragiketa-eskuliburua"]},{"id":"backup","g":"run","word":"Babeskopia","text":"Zure datuen lehenagoko kopia gorde bat, zerbait galdu edo hondatzen bada erabiltzeko. AI-gile-k zure taulen babeskopia bat egiten du egunero.","also":["babeskopiak","backup"]},{"id":"restore","g":"run","word":"Berreskuratzea","text":"Babeskopia batetik datuak berriro ekartzea. Babeskopia batek benetan balio du berreskura daitekeela dakizunean bakarrik, beraz merezi du noizean behin probatzea.","also":["berreskuratu","berreskuratuta"]},{"id":"backlog","g":"team","word":"Backlog","text":"Oraindik planifikatu gabeko ideiak eta lana. Ez da ezer lantzen Egiteko zutabera pasatu arte."},{"id":"sprint","g":"team","word":"Sprint","text":"Lan-tarte labur bat (askotan aste bat edo bi), amaitzeko adostutako txartel multzo batekin.","also":["sprintak","sprint-ak"]},{"id":"standup","g":"team","word":"Stand-up","text":"Egiaztapen azkar bat: talde-kide bakoitzak zer egin duen, zer egingo duen eta zerk geldiarazten duen.","also":["standup","stand-up-ak","standupak"]},{"id":"kanban","g":"team","word":"Kanban","text":"Zutabeak dituen taula (Egiteko, Egiten, Eginda), non txartelak ezkerretik eskuinera mugitzen diren lana egin ahala."},{"id":"wip","g":"team","word":"WIP muga","text":"Egiten ari den lana: zutabe batek izan beharko lukeen txartel kopuru handiena, taldeak gauzak amai ditzan gehiago hasi aurretik.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"Taldearen egiaztapen-zerrenda laburra «amaituta» zer den esateko, probatuta eta azalduta adibidez, txartel bat zuri eman aurretik. Bere bikia, Definition of Ready, txartel bat hasteko bezain argi noiz dagoen esaten du.","also":["Definition of Ready","eginda egotearen definizioa"]},{"id":"testpile","g":"team","word":"Proba-pila","text":"Zuk probatzeko zain dauden amaitutako txartelak, bata bestearen atzetik. Onartu bat edo itzuli ohar batekin, eta hurrengoa agertzen da.","also":["proba-pilak"]},{"id":"retro","g":"team","word":"Retro","text":"Taldeak nola lan egiten duen atzera begiratzea, hobeto egiteko gauza bat adosteko. AI-gile-n retro batek taldearen lan egiteko moduan aldaketa bat proposatzen du, eta zuk Go edo Oraindik ez esaten duzu.","also":["retroak","erretrospektiba","erretrospektibak"]},{"id":"peerreview","g":"team","word":"Berdinen arteko berrikuspena","text":"Bigarren begi pare bat: beste AI batek txartel bakoitzaren lana egiaztatzen du zuregana iritsi aurretik, akats gutxiago pasa daitezen.","also":["kode-berrikuspena","code review","peer review"]},{"id":"swarm","g":"team","word":"Erlauntza","text":"Esku guztiak lanera: talde bakoitzak beste lana uzten du proiektu premiazko bati laguntzeko, konpondu arte. Beste proiektuek itxaron egiten dute bitartean.","also":["swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Lana aurrera doala zaintzen duena: trabatutako txartelak antzematen ditu, taldeei bultzadatxo bat ematen die eta zain dagoena gogorarazten dizu. AI-gile-n Lead Scrum Master-ak egiten du hori proiektu guztietan.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agente","text":"Zeregin batean bere kabuz lan egiten duen AI bat: kodea irakurtzen du, aldaketak egiten ditu, egiaztapenak exekutatzen ditu eta berri ematen du.","also":["agenteak"]},{"id":"token","g":"team","word":"Token","text":"AI erabilera zenbatzeko unitatea: gutxi gorabehera irakurritako edo idatzitako testuaren letra batzuk. Zenbat eta token gutxiago, orduan eta plan gehiago geratzen zaizu.","also":["token-ak","tokenak"]},{"id":"hook","g":"team","word":"Hook","text":"Une jakin batean bere kabuz exekutatzen den komando txiki bat, adib. AI saio bat hasten denean, taldeak zure iruzkinak entzun ditzan.","also":["hook-ak","hookak"]}]}};
